package com.qfc.rag;
import com.baomidou.mybatisplus.annotation.*; import java.time.LocalDateTime;
@TableName("knowledge_chunk") public class KnowledgeChunk { @TableId(type=IdType.AUTO) private Long id; private Long knowledgeFileId; private Integer chunkNo; private String content,locator; private LocalDateTime createdAt; public Long getId(){return id;} public void setId(Long v){id=v;} public Long getKnowledgeFileId(){return knowledgeFileId;} public void setKnowledgeFileId(Long v){knowledgeFileId=v;} public Integer getChunkNo(){return chunkNo;} public void setChunkNo(Integer v){chunkNo=v;} public String getContent(){return content;} public void setContent(String v){content=v;} public String getLocator(){return locator;} public void setLocator(String v){locator=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} }
